drop schema if exists costing cascade; create schema costing;
create table costing.product_production_overhead_workload_snapshot(refresh_run_id bigint,valuation_date date default '2026-09-10',product_id bigint,workload_units numeric,rounded_batch_count numeric,preferred_batch_size numeric,monthly_product_base_qty numeric,company_ready_workload_units numeric,workload_status text);
create table costing.product_direct_labour_workload_snapshot(refresh_run_id bigint,product_id bigint,direct_labour_workload_units numeric,standard_batch_count numeric,company_eligible_workload_units numeric,direct_labour_pool_amount numeric,monthly_product_base_qty numeric,product_direct_labour_allocation numeric);
create table costing.sku_production_overhead_allocation_snapshot(refresh_run_id bigint,sku_id bigint,product_id bigint,sku_base_qty_per_unit numeric,monthly_sku_base_qty numeric,production_overhead_cost_per_sku numeric,production_overhead_pool_amount numeric,production_overhead_cost_per_base_uom numeric,product_production_overhead_allocation numeric);
create table costing.sku_direct_labour_allocation_snapshot(refresh_run_id bigint,sku_id bigint,product_id bigint,sku_base_qty_per_unit numeric,manufacturing_direct_labour_cost_per_sku numeric,packing_labour_cost_per_sku numeric,direct_labour_cost_per_sku numeric,resolved_sales_base_qty numeric);
create function costing.fn_resolve_manufacturing_standard_rate(a text,b text,c date) returns table(standard_rate numeric) language sql as $$ select 706203/5516.35::numeric $$;
update costing.sku_production_overhead_allocation_snapshot set product_production_overhead_allocation=production_overhead_cost_per_sku/nullif(sku_base_qty_per_unit,0)*monthly_sku_base_qty;
create table costing.before_poh as select * from costing.sku_production_overhead_allocation_snapshot; create table costing.before_dl as select * from costing.sku_direct_labour_allocation_snapshot;
